/* Markup: <div class="fx-laser" data-text="LASER">LASER</div> */

/* Colour tokens — override to re-skin the effect:
   --ink    main text colour (defaults to currentColor)
   --ink-2  primary accent   --ink-3  secondary accent */
:root { --ink: currentColor; --ink-2: #FF4FD8; --ink-3: #4FF8FF; }

/* 47 Laser-Cut */
.fx-laser {
  position: relative;
  font: 600 34px/1.08 JetBrains Mono, monospace;
  letter-spacing: .12em;
  color: var(--ink);
}
.fx-laser:before {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  color: var(--ink-2);
  clip-path: inset(44% 0 42% 0);
  text-shadow: 0 0 10px var(--ink-2);
  animation: fx-laser-slice 2.2s ease-in-out infinite;
}
.fx-laser:after {
  content: "";
  position: absolute;
  left: -8%;
  top: 49%;
  width: 116%;
  height: 2px;
  background: linear-gradient(90deg, transparent, #fff, var(--ink-2), transparent);
  box-shadow: 0 0 13px var(--ink-2);
  animation: fx-laser 2.2s ease-in-out infinite;
}
@keyframes fx-laser {
  0%,to {
    transform: translateY(-14px) scaleX(.35);
    opacity: 0;
  }
  44%,58% {
    transform: translateY(0) scaleX(1);
    opacity: 1;
  }
}
@keyframes fx-laser-slice {
  0%,to {
    transform: translate(0);
    opacity: .2;
  }
  50% {
    transform: translate(5px);
    opacity: 1;
  }
}
